"""Stile grafico originale Venduti Subito, disponibile in tutte le pagine."""

GLOBAL_STYLE = "<style>\n\n:root {\n    --mt-bg: #f5f7fb;\n    --mt-card: rgba(255,255,255,0.78);\n    --mt-border: rgba(15,23,42,0.08);\n    --mt-text: #0f172a;\n    --mt-muted: #64748b;\n    --mt-blue: #2563eb;\n    --mt-violet: #7c3aed;\n}\n\n.stApp {\n    background:\n        radial-gradient(circle at 8% 0%, rgba(37,99,235,0.10), transparent 30%),\n        radial-gradient(circle at 94% 8%, rgba(124,58,237,0.09), transparent 28%),\n        linear-gradient(180deg, #fbfdff 0%, #f6f8fc 48%, #eef3f9 100%);\n}\n\n.block-container {\n    max-width: 1500px;\n    padding-top: 1.25rem;\n    padding-bottom: 4rem;\n    padding-left: 2.2rem;\n    padding-right: 2.2rem;\n}\n\nhtml, body, [class*=\"css\"] {\n    font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n}\n\nh1, h2, h3 {\n    color: var(--mt-text);\n    letter-spacing: -0.03em;\n}\n\nh1 {\n    font-size: 2.25rem !important;\n    font-weight: 900 !important;\n}\n\nh2 {\n    font-size: 1.45rem !important;\n    font-weight: 800 !important;\n}\n\nh3 {\n    font-weight: 800 !important;\n}\n\n/* HERO */\n.mt-hero {\n    position: relative;\n    overflow: hidden;\n    border-radius: 28px;\n    padding: 28px 30px;\n    margin-bottom: 1.6rem;\n    color: white;\n    background:\n        radial-gradient(circle at 92% 12%, rgba(168,85,247,0.34), transparent 28%),\n        radial-gradient(circle at 8% 90%, rgba(59,130,246,0.28), transparent 35%),\n        linear-gradient(135deg, #0f172a 0%, #172554 56%, #312e81 100%);\n    box-shadow: 0 20px 48px rgba(15,23,42,0.18);\n}\n\n.mt-hero::after {\n    content: \"\";\n    position: absolute;\n    width: 220px;\n    height: 220px;\n    border-radius: 50%;\n    right: -90px;\n    bottom: -120px;\n    background: rgba(255,255,255,0.07);\n}\n\n.mt-hero-top {\n    display: flex;\n    justify-content: space-between;\n    align-items: flex-start;\n    gap: 18px;\n    position: relative;\n    z-index: 1;\n}\n\n.mt-hero-title {\n    font-size: 2rem;\n    line-height: 1.08;\n    font-weight: 900;\n    letter-spacing: -0.04em;\n    margin-bottom: 8px;\n}\n\n.mt-hero-subtitle {\n    color: rgba(255,255,255,0.72);\n    font-size: 0.98rem;\n}\n\n.mt-live {\n    display: inline-flex;\n    align-items: center;\n    gap: 8px;\n    padding: 8px 12px;\n    border-radius: 999px;\n    background: rgba(255,255,255,0.11);\n    border: 1px solid rgba(255,255,255,0.15);\n    font-size: 0.78rem;\n    font-weight: 800;\n    white-space: nowrap;\n}\n\n.mt-live-dot {\n    width: 8px;\n    height: 8px;\n    border-radius: 50%;\n    background: #4ade80;\n    box-shadow: 0 0 0 0 rgba(74,222,128,0.5);\n    animation: mtPulse 1.8s infinite;\n}\n\n@keyframes mtPulse {\n    0% { box-shadow: 0 0 0 0 rgba(74,222,128,0.55); }\n    70% { box-shadow: 0 0 0 8px rgba(74,222,128,0); }\n    100% { box-shadow: 0 0 0 0 rgba(74,222,128,0); }\n}\n\n/* SIDEBAR */\nsection[data-testid=\"stSidebar\"] {\n    background: linear-gradient(180deg, rgba(255,255,255,0.94), rgba(248,250,252,0.90));\n    border-right: 1px solid var(--mt-border);\n    /* niente blur globale: più fluido durante scroll e rerun */\n}\n\nsection[data-testid=\"stSidebar\"] > div {\n    padding-top: 1.2rem;\n}\n\ndiv[data-testid=\"stSidebarNav\"] a {\n    border-radius: 13px;\n    margin-bottom: 5px;\n    transition: all 0.18s ease;\n    font-weight: 700;\n}\n\ndiv[data-testid=\"stSidebarNav\"] a:hover {\n    background: rgba(37,99,235,0.08);\n    transform: translateX(2px);\n}\n\n/* KPI */\ndiv[data-testid=\"stMetric\"] {\n    border: 1px solid rgba(255,255,255,0.82);\n    border-radius: 20px;\n    padding: 18px 20px;\n    min-height: 118px;\n    background: rgba(255,255,255,0.72);\n    box-shadow: 0 10px 28px rgba(15,23,42,0.06);\n    position: relative;\n    overflow: hidden;\n    transition: transform 0.18s ease, box-shadow 0.18s ease;\n}\n\ndiv[data-testid=\"stMetric\"]::before {\n    content: \"\";\n    position: absolute;\n    top: 0;\n    left: 0;\n    width: 100%;\n    height: 4px;\n    background: linear-gradient(90deg, var(--mt-blue), var(--mt-violet));\n}\n\ndiv[data-testid=\"stMetric\"]:hover {\n    box-shadow: 0 12px 28px rgba(15,23,42,0.08);\n}\n\ndiv[data-testid=\"stMetricLabel\"] {\n    font-size: 0.88rem;\n    font-weight: 700;\n    color: var(--mt-muted);\n}\n\ndiv[data-testid=\"stMetricValue\"] {\n    font-size: 1.8rem;\n    font-weight: 900;\n    letter-spacing: -0.04em;\n    color: var(--mt-text);\n}\n\n/* CARD / CONTAINER */\ndiv[data-testid=\"stVerticalBlockBorderWrapper\"] {\n    border-radius: 20px;\n    border-color: rgba(255,255,255,0.82);\n    background: rgba(255,255,255,0.62);\n    box-shadow: 0 10px 26px rgba(15,23,42,0.05);\n}\n\n/* INPUT */\ndiv[data-baseweb=\"input\"] > div,\ndiv[data-baseweb=\"select\"] > div {\n    border-radius: 13px !important;\n    background: rgba(255,255,255,0.92) !important;\n    border-color: rgba(15,23,42,0.08) !important;\n    box-shadow: 0 4px 12px rgba(15,23,42,0.03);\n}\n\n/* BUTTON */\n.stButton > button,\n.stDownloadButton > button {\n    border-radius: 13px;\n    font-weight: 800;\n    min-height: 42px;\n    border: 1px solid rgba(15,23,42,0.08);\n    background: linear-gradient(180deg, #ffffff 0%, #f7f9fc 100%);\n    box-shadow: 0 7px 16px rgba(15,23,42,0.05);\n    transition: all 0.18s ease;\n}\n\n.stButton > button:hover,\n.stDownloadButton > button:hover {\n    box-shadow: 0 10px 20px rgba(15,23,42,0.08);\n    border-color: rgba(37,99,235,0.18);\n}\n\n/* TABLES */\ndiv[data-testid=\"stDataFrame\"] {\n    border: 1px solid rgba(255,255,255,0.82);\n    border-radius: 18px;\n    overflow: hidden;\n    box-shadow: 0 10px 24px rgba(15,23,42,0.05);\n    background: rgba(255,255,255,0.72);\n}\n\n/* CHARTS */\ndiv[data-testid=\"stVegaLiteChart\"],\ndiv[data-testid=\"stPlotlyChart\"] {\n    border: 1px solid rgba(255,255,255,0.82);\n    border-radius: 18px;\n    padding: 10px;\n    background: rgba(255,255,255,0.66);\n    box-shadow: 0 10px 24px rgba(15,23,42,0.04);\n    backdrop-filter: blur(10px);\n}\n\n/* EXPANDER */\ndetails {\n    border-radius: 16px !important;\n    overflow: hidden;\n}\n\nhr {\n    margin-top: 2rem !important;\n    margin-bottom: 2rem !important;\n    opacity: 0.12;\n}\n\ndiv[data-testid=\"stCaptionContainer\"] {\n    margin-bottom: 1.15rem;\n    color: var(--mt-muted);\n}\n\n@media (prefers-reduced-motion: reduce) {\n    *, *::before, *::after {\n        animation-duration: 0.01ms !important;\n        animation-iteration-count: 1 !important;\n        transition-duration: 0.01ms !important;\n        scroll-behavior: auto !important;\n    }\n}\n\n@media (max-width: 700px) {\n    .block-container {\n        padding-left: 1rem;\n        padding-right: 1rem;\n    }\n\n    .mt-hero {\n        padding: 21px;\n        border-radius: 22px;\n    }\n\n    .mt-hero-top {\n        flex-direction: column;\n    }\n\n    .mt-hero-title {\n        font-size: 1.55rem;\n    }\n}\n\n</style>"
